// Browser-only interaction layer. The assistant never makes network requests.
(() => {
  const q=s=>document.querySelector(s);
  const text=(zh,en)=>lang==='zh'?zh:en;
  const carousel=q('#home'),panels=[...document.querySelectorAll('[data-hero-slide]')],dots=[...document.querySelectorAll('[data-slide]')];
  let slide=0,autoPaused=false,carouselVisible=true,carouselTimer;
  function selectSlide(index){slide=(index+3)%3;panels.forEach((panel,i)=>{const active=i===slide;panel.classList.toggle('is-active',active);panel.setAttribute('aria-hidden',String(!active));panel.inert=!active;});dots.forEach((dot,i)=>{dot.classList.toggle('selected',i===slide);if(i===slide)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current');});document.querySelectorAll('[data-theme]').forEach((theme,i)=>theme.hidden=i!==slide);}
  function stopAuto(){clearTimeout(carouselTimer);}
  function startAuto(){stopAuto();if(reduceMotion||autoPaused||document.hidden||!carouselVisible||carousel.contains(document.activeElement))return;carouselTimer=setTimeout(()=>{selectSlide(slide+1);startAuto();},6000);}
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>{selectSlide(i);startAuto();}));
  carousel.addEventListener('focusin',stopAuto);carousel.addEventListener('focusout',()=>requestAnimationFrame(startAuto));
  document.addEventListener('visibilitychange',()=>document.hidden?stopAuto():startAuto());
  new IntersectionObserver(entries=>{carouselVisible=entries[0].isIntersecting;startAuto();},{threshold:.3}).observe(carousel);
  const pause=q('#explore-pause');function pauseLabel(){pause.textContent=text(autoPaused?'播放自動輪播':'暫停自動輪播',autoPaused?'Play carousel':'Pause carousel');pause.setAttribute('aria-pressed',String(autoPaused));}
  pause.addEventListener('click',()=>{autoPaused=!autoPaused;pauseLabel();startAuto();});
  let pointerStart=null;carousel.addEventListener('pointerdown',e=>{if(e.target.closest('a,button')||e.pointerType==='mouse')return;pointerStart={x:e.clientX,y:e.clientY};stopAuto();},{passive:true});carousel.addEventListener('pointerup',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;pointerStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)selectSlide(slide+(dx<0?1:-1));startAuto();},{passive:true});carousel.addEventListener('pointercancel',()=>{pointerStart=null;startAuto();});
  startAuto();
  const hap=q('.hap-art'),motion=q('#hap-motion');
  function motionLabel(){const paused=hap.classList.contains('paused');motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',text(paused?'播放圖樣動畫':'暫停圖樣動畫',paused?'Play animation':'Pause animation'));motion.querySelector('.motion-icon').textContent=paused?'▷':'Ⅱ';const label=motion.querySelector('[data-zh]');label.dataset.zh=paused?'播放動畫':'暫停動畫';label.dataset.en=paused?'Play animation':'Pause animation';label.textContent=label.dataset[lang];}
  if(reduceMotion){hap.classList.add('paused');motion.hidden=true;}
  motion.addEventListener('click',()=>{hap.classList.toggle('paused');motionLabel();});motionLabel();
  // Keep the footer a single accessible link while its visual letters react individually.
  const wordmark=q('.footer-wordmark');wordmark.setAttribute('aria-label','RS Technologies — '+text('返回頂部','Back to top'));
  wordmark.replaceChildren();const letters=document.createElement('span');letters.className='footer-letters';letters.setAttribute('aria-hidden','true');
  ['RS','TECHNOLOGIES'].forEach(word=>{const group=document.createElement('span');group.className='footer-word';[...word].forEach(char=>{const letter=document.createElement('span');letter.className='footer-letter';letter.textContent=char;letter.addEventListener('pointerenter',()=>animateLetter(letter));letter.addEventListener('animationend',()=>letter.classList.remove('jelly'));group.append(letter);});letters.append(group);});
  const arrow=document.createElement('span');arrow.className='footer-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';wordmark.append(letters,arrow);
  function animateLetter(el){if(reduceMotion)return;el.classList.remove('jelly');requestAnimationFrame(()=>el.classList.add('jelly'));}
  function wave(){if(reduceMotion)return;wordmark.querySelectorAll('.footer-letter').forEach((el,i)=>setTimeout(()=>animateLetter(el),i*36));}
  wordmark.addEventListener('pointerenter',wave);wordmark.addEventListener('focus',wave);
  const footerHint=document.createElement('p');footerHint.className='footer-invitation';footerHint.dataset.zh='移動游標，讓靈感跳動。';footerHint.dataset.en='Move your cursor. Set ideas in motion.';footerHint.textContent=footerHint.dataset[lang];wordmark.before(footerHint);
  const form=q('#quote-form');
  function formLabels(){const placeholders={name:['如何稱呼您？','How should we address you?'],company:['您的公司名稱','Your company name'],email:['name@company.com','name@company.com'],message:['例如：希望整合現有系統、優化 IT 支援…','For example: integrate existing systems or improve IT support…']};Object.entries(placeholders).forEach(([name,values])=>form.elements[name].placeholder=values[lang==='zh'?0:1]);}
  form.querySelectorAll('input,textarea,select').forEach(input=>{input.addEventListener('input',()=>{input.closest('label').classList.toggle('completed',Boolean(input.value.trim())&&input.checkValidity());});});formLabels();
  const assistant=q('#site-assistant'),messages=q('#assistant-messages'),input=q('#assistant-input');
  const faqs=[
    {id:'services',question:['你們提供哪些服務？','What services do you offer?'],aliases:['服務','服务','有哪些服務','有哪些服务','你們有什麼服務','你们有什么服务','你們提供哪些服務','你们提供哪些服务','services','what services do you offer','what services are available'],answer:()=>services.map(s=>lang==='zh'?s.zh:s.en).join('、')+text('。詳情可查看服務區，或點擊卡片了解各項服務。','. Explore the service cards for details.'),source:'#solutions',sourceLabel:['查看服務區','View solutions']},
    {id:'hap',question:['HAP 可以做甚麼？','What can HAP do?'],aliases:['hap','hap可以做什麼','hap可以做什么','hap可以做甚麼','什麼是hap','什么是hap','what is hap','what can hap do','nocoly'],answer:()=>pick(services[4].desc),source:'#solutions',sourceLabel:['查看 HAP 服務','View HAP services']},
    {id:'security',question:['有哪些安全系統？','What security systems are available?'],aliases:['安全系統','安全系统','有哪些安全系統','有哪些安全系统','cctv','security systems','what security systems are available'],answer:()=>pick(services[3].desc),source:'#solutions',sourceLabel:['查看安全系統服務','View security services']},
    {id:'about',question:['公司在哪裡發展？','Where does the company operate?'],aliases:['公司介紹','公司介绍','公司在哪裡發展','公司在哪里发展','公司什麼時候成立','公司什么时候成立','何時成立','成立時間','成立时间','about','about the company','where does the company operate','when was the company established'],answer:()=>[...document.querySelectorAll('.about-grid .body-copy')].map(e=>e.textContent).join('\n\n'),source:'#about',sourceLabel:['查看公司介紹','View company information']},
    {id:'certs',question:['公司有哪些專業認證？','Which certifications are listed?'],aliases:['認證','认证','專業認證','专业认证','公司有哪些專業認證','公司有哪些专业认证','iso','certifications','which certifications are listed'],answer:()=>text('網站列出的專業標準包括：','The website lists: ')+[...document.querySelectorAll('.certs b')].map(e=>e.innerText.replace(/\s+/g,' ')).join(lang==='zh'?'；':'; ')+text('。','.'),source:'#standards',sourceLabel:['查看專業認證','View professional standards']},
    {id:'csr',question:['你們如何保護環境？','How do you support the environment?'],aliases:['環保','环保','環境保護','环境保护','csr','你們如何保護環境','你们如何保护环境','environment','how do you support the environment'],answer:()=>pick(csr[0].desc)+'\n\n'+pick(csr[0].items).join('\n'),source:'#CSR',sourceLabel:['查看企業社會責任','View responsibility']},
    {id:'brands',question:['網站有哪些合作品牌？','Which brands are shown?'],aliases:['品牌','合作品牌','有哪些品牌','網站有哪些合作品牌','网站有哪些合作品牌','brands','which brands are shown'],answer:()=>text('網站品牌區展示：','The brand section shows: ')+[...document.querySelectorAll('.logo-cell img')].map(i=>i.alt).join('、')+text('。','. '),source:'#partners',sourceLabel:['查看品牌區','View technology brands']},
    {id:'contact',question:['如何聯絡公司？','How can I contact the company?'],aliases:['聯絡','联系','聯繫','如何聯絡公司','如何联系公司','電話','电话','電郵','邮箱','地址','contact','how can i contact the company','email','phone','address'],answer:()=>text('電話：+852 3101 0403\n電郵：sales@rstech.com.hk\n地址：九龍九龍灣宏泰道12號榮發工業大廈3樓310室。','Phone: +852 3101 0403\nEmail: sales@rstech.com.hk\nAddress: Room 310, 3/F, Wing Fat Industrial Building, 12 Wang Tai Road, Kowloon Bay, Kowloon.'),source:'#contact',sourceLabel:['聯絡公司','Contact the company']}
  ];
  const normalize=s=>s.normalize('NFKC').toLowerCase().replace(/[\s?？!！。.,，、:：;；]+/g,'').trim();
  function addMessage(body,type='bot',item=null){const node=document.createElement('div');node.className='chat-message '+type;node.textContent=body;if(item){const cite=document.createElement('span');cite.className='chat-source';cite.textContent=text('資料來源：本站已展示內容','Source: information displayed on this website');const link=document.createElement('a');link.href=item.source;link.textContent=pick(item.sourceLabel)+' ↗';link.dataset.assistantNavigate='';node.append(cite,link);}messages.append(node);while(messages.children.length>35)messages.firstChild.remove();messages.scrollTop=messages.scrollHeight;return node;}
  function fallback(){const node=addMessage(text('這個問題超出本站目前展示的資料，或未對應到固定問題。我無法提供未經網站確認的答案。\n\n價格、服務承諾、個別項目及其他詳細問題，請直接聯絡公司協助解決。','This question is outside the information currently displayed on this website, or does not match a curated question. I cannot supply an answer that the website does not confirm.\n\nPlease contact the company for pricing, service commitments, project-specific needs or other details.'));const contact=document.createElement('a');contact.href='#contact';contact.dataset.assistantNavigate='';contact.className='assistant-contact-link';contact.textContent=text('聯絡公司 ↗','Contact the company ↗');const email=document.createElement('a');email.href='mailto:sales@rstech.com.hk';email.textContent='sales@rstech.com.hk';node.append(contact,email);messages.scrollTop=messages.scrollHeight;}
  function ask(value,id){const question=value.trim();if(!question)return;addMessage(question,'user');const clean=normalize(question);const item=id?faqs.find(f=>f.id===id):faqs.find(f=>[...f.question,...f.aliases].some(a=>normalize(a)===clean));if(item)addMessage(item.answer(),'bot',item);else fallback();}
  function renderAssistant(){q('#assistant-faqs').replaceChildren();faqs.forEach(f=>{const b=document.createElement('button');b.type='button';b.textContent=pick(f.question);b.addEventListener('click',()=>ask(pick(f.question),f.id));q('#assistant-faqs').append(b);});input.placeholder=text('例如：你們提供哪些服務？','Example: What services do you offer?');q('#assistant-toggle').setAttribute('aria-label',text('開啟本站知識助手','Open website assistant'));q('#assistant-close').setAttribute('aria-label',text('關閉問答助手','Close website assistant'));q('#assistant-form button').setAttribute('aria-label',text('詢問','Ask'));messages.replaceChildren();addMessage(text('您好，我是本站知識助手。可點選下方問題，了解這個網站已展示的服務與公司資訊。\n\n我使用固定答案，不查詢外部資料；未收錄的問題會引導您聯絡公司。','Hello. I can help you explore the services and company information displayed on this website. Choose a question below.\n\nI use curated answers and do not search external sources. For unlisted questions, I will help you contact the company.'));}
  q('#assistant-toggle').addEventListener('click',()=>{assistant.showModal();input.focus();});q('#assistant-close').addEventListener('click',()=>assistant.close());assistant.addEventListener('close',()=>q('#assistant-toggle').focus());
  q('#assistant-form').addEventListener('submit',e=>{e.preventDefault();ask(input.value);input.value='';input.focus();});
  assistant.addEventListener('click',e=>{const link=e.target.closest('[data-assistant-navigate]');if(link){if(link.hash==='#CSR'){csrIndex=0;renderCSR();}assistant.close();}});
  q('#language').addEventListener('click',()=>{formLabels();motionLabel();renderAssistant();wordmark.setAttribute('aria-label','RS Technologies — '+text('返回頂部','Back to top'));dots.forEach((dot,i)=>dot.setAttribute('aria-label',text('第 '+(i+1)+' 張卡片','Slide '+(i+1))));pauseLabel();});
  renderAssistant();
})();
